from collections import *

def encode(message):
    vowels = set('aeiouAEIOU')

    def swap_case_and_replace_vowels(c):
        if c.isalpha():
            swapped = c.swapcase()
            if swapped.lower() in vowels:
                next_vowel = chr(ord(swapped.lower()) + 2)
                return next_vowel.swapcase() if swapped.islower() else next_vowel.upper()
            return swapped
        return c

    return ''.join(swap_case_and_replace_vowels(c) for c in message)

